-- API account and watchlist tables. Existing user_roles and user_watchlist are untouched.
CREATE TABLE IF NOT EXISTS public."Users" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(100) NOT NULL,
  "Email" varchar(320) NOT NULL,
  "PasswordHash" text NOT NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_Email" ON public."Users" ("Email");

CREATE TABLE IF NOT EXISTS public."WatchlistEntries" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserAccountId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE CASCADE,
  "MovieId" integer NOT NULL REFERENCES public.movies("id") ON DELETE CASCADE,
  "AddedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "AK_WatchlistEntries_UserAccountId_MovieId" UNIQUE ("UserAccountId", "MovieId")
);

-- SAFE, ADDITIVE MFB Cinema migration for the existing Supabase schema.
-- Does not drop, rename, truncate, or recreate existing tables or movie rows.
-- Back up the database before applying. Run once in Supabase SQL Editor.
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS genre text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS backdrop_url text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'Film';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS runtime text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS rating double precision NOT NULL DEFAULT 0;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS director text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS cast_names text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS language text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS country text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS is_featured boolean NOT NULL DEFAULT false;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS is_published boolean NOT NULL DEFAULT true;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS popularity integer NOT NULL DEFAULT 0;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS release_date timestamp with time zone NULL;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS synopsis text NOT NULL DEFAULT '';

-- Ensure new catalogue records receive an ID without resetting existing IDs.
CREATE SEQUENCE IF NOT EXISTS public.movies_id_seq;
SELECT setval('public.movies_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM public.movies), 0), 1), COALESCE((SELECT MAX(id) FROM public.movies), 0) > 0);
ALTER TABLE public.movies ALTER COLUMN id SET DEFAULT nextval('public.movies_id_seq');
ALTER SEQUENCE public.movies_id_seq OWNED BY public.movies.id;

-- Keep the original genres text[] and description columns intact.
UPDATE public.movies SET genre = COALESCE(genres[1], '') WHERE genre = '';
UPDATE public.movies SET synopsis = COALESCE(description, '') WHERE synopsis = '';

-- Idempotent additive migration for the optional ASP.NET Core API database.
-- Additive/idempotent schema update. Known metadata defaults are backfilled conservatively; no rows are dropped.
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "backdrop_url" text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "kind" text NOT NULL DEFAULT 'Film';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "runtime" text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "rating" double precision NOT NULL DEFAULT 0;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "director" text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "cast_names" text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "language" text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "country" text NOT NULL DEFAULT '';
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "is_featured" boolean NOT NULL DEFAULT false;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "is_published" boolean NOT NULL DEFAULT true;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "popularity" integer NOT NULL DEFAULT 0;
ALTER TABLE public.movies ADD COLUMN IF NOT EXISTS "release_date" timestamp with time zone NULL;
CREATE INDEX IF NOT EXISTS "IX_Movies_Kind_Year" ON public.movies ("kind", "year" DESC);
CREATE INDEX IF NOT EXISTS "IX_Movies_IsPublished_Popularity" ON public.movies ("is_published", "popularity" DESC);
