CREATE TABLE IF NOT EXISTS public."Favorites" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserAccountId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE CASCADE,
  "MovieId" integer NOT NULL REFERENCES public.movies("id") ON DELETE CASCADE,
  "CreatedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "AK_Favorites_UserAccountId_MovieId" UNIQUE ("UserAccountId", "MovieId")
);
CREATE TABLE IF NOT EXISTS public."WatchHistory" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserAccountId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE CASCADE,
  "MovieId" integer NOT NULL REFERENCES public.movies("id") ON DELETE CASCADE,
  "PositionSeconds" integer NOT NULL DEFAULT 0,
  "DurationSeconds" integer NULL,
  "LastWatchedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "AK_WatchHistory_UserAccountId_MovieId" UNIQUE ("UserAccountId", "MovieId")
);
CREATE INDEX IF NOT EXISTS "IX_WatchHistory_UserAccountId_LastWatchedAtUtc" ON "WatchHistory" ("UserAccountId", "LastWatchedAtUtc" DESC);
CREATE TABLE IF NOT EXISTS public."Ratings" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserAccountId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE CASCADE,
  "MovieId" integer NOT NULL REFERENCES public.movies("id") ON DELETE CASCADE,
  "Rating" integer NOT NULL CHECK ("Rating" BETWEEN 1 AND 5),
  "UpdatedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "AK_Ratings_UserAccountId_MovieId" UNIQUE ("UserAccountId", "MovieId")
);
CREATE TABLE IF NOT EXISTS public."Reviews" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserAccountId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE CASCADE,
  "MovieId" integer NOT NULL REFERENCES public.movies("id") ON DELETE CASCADE,
  "DisplayName" character varying(100) NOT NULL DEFAULT 'Member',
  "Rating" integer NOT NULL CHECK ("Rating" BETWEEN 1 AND 5),
  "Comment" character varying(600) NOT NULL DEFAULT '',
  "IsHidden" boolean NOT NULL DEFAULT false,
  "CreatedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  "UpdatedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "AK_Reviews_UserAccountId_MovieId" UNIQUE ("UserAccountId", "MovieId")
);
CREATE INDEX IF NOT EXISTS "IX_Reviews_MovieId_CreatedAtUtc" ON "Reviews" ("MovieId", "CreatedAtUtc" DESC);
CREATE TABLE IF NOT EXISTS public."Seasons" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SeriesId" integer NOT NULL REFERENCES public.movies("id") ON DELETE CASCADE,
  "SeasonNumber" integer NOT NULL CHECK ("SeasonNumber" >= 1),
  "Title" character varying(180) NOT NULL DEFAULT '',
  "PosterUrl" text NOT NULL DEFAULT '',
  "ReleaseDate" timestamp with time zone NULL,
  CONSTRAINT "AK_Seasons_SeriesId_SeasonNumber" UNIQUE ("SeriesId", "SeasonNumber")
);
CREATE TABLE IF NOT EXISTS public."Episodes" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "SeasonId" integer NOT NULL REFERENCES "Seasons"("Id") ON DELETE CASCADE,
  "EpisodeNumber" integer NOT NULL CHECK ("EpisodeNumber" >= 1),
  "Title" character varying(180) NOT NULL,
  "Synopsis" text NOT NULL DEFAULT '',
  "RuntimeMinutes" integer NULL CHECK ("RuntimeMinutes" IS NULL OR "RuntimeMinutes" > 0),
  "StillUrl" text NOT NULL DEFAULT '',
  "AirDate" timestamp with time zone NULL,
  CONSTRAINT "AK_Episodes_SeasonId_EpisodeNumber" UNIQUE ("SeasonId", "EpisodeNumber")
);
CREATE TABLE IF NOT EXISTS public."Notifications" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserAccountId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE CASCADE,
  "Type" character varying(40) NOT NULL DEFAULT 'system',
  "Title" character varying(180) NOT NULL,
  "Message" character varying(1000) NOT NULL DEFAULT '',
  "PayloadJson" text NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  "ReadAtUtc" timestamp with time zone NULL
);
CREATE INDEX IF NOT EXISTS "IX_Notifications_UserAccountId_CreatedAtUtc" ON "Notifications" ("UserAccountId", "CreatedAtUtc" DESC);
CREATE TABLE IF NOT EXISTS public."WatchPartyRooms" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoomCode" character varying(12) NOT NULL UNIQUE,
  "HostUserAccountId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE CASCADE,
  "MovieId" integer NOT NULL REFERENCES public.movies("id") ON DELETE CASCADE,
  "IsActive" boolean NOT NULL DEFAULT true,
  "IsPlaying" boolean NOT NULL DEFAULT false,
  "PositionSeconds" double precision NOT NULL DEFAULT 0,
  "UpdatedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  "CreatedAtUtc" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public."WatchPartyParticipants" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoomId" integer NOT NULL REFERENCES "WatchPartyRooms"("Id") ON DELETE CASCADE,
  "UserAccountId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE CASCADE,
  "JoinedAtUtc" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "AK_WatchPartyParticipants_RoomId_UserAccountId" UNIQUE ("RoomId", "UserAccountId")
);
CREATE TABLE IF NOT EXISTS public."CastMembers" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" character varying(180) NOT NULL,
  "ProfileUrl" character varying(2048) NOT NULL DEFAULT '',
  "Biography" text NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS public."ContentCastCredits" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MovieId" integer NOT NULL REFERENCES public.movies("id") ON DELETE CASCADE,
  "CastMemberId" integer NOT NULL REFERENCES "CastMembers"("Id") ON DELETE CASCADE,
  "CharacterName" character varying(180) NOT NULL DEFAULT '',
  "CreditOrder" integer NOT NULL DEFAULT 0,
  CONSTRAINT "AK_ContentCastCredits_MovieId_CastMemberId" UNIQUE ("MovieId", "CastMemberId")
);
CREATE INDEX IF NOT EXISTS "IX_ContentCastCredits_MovieId_CreditOrder" ON "ContentCastCredits" ("MovieId", "CreditOrder");
